def digit_sum(n):
    if n == 0:
        return 0
    return n % 10 + digit_sum(n // 10)

def rev(s):
    if s == "":
        return ""
    return rev(s[1:]) + s[0]

def is_pal(s):
    if len(s) <= 1:
        return True
    return s[0] == s[-1] and is_pal(s[1:-1])

print(digit_sum(4907), rev("braude"), is_pal("level"), is_pal("lever"))

